import pytest
from roman import to_roman, from_roman


@pytest.mark.parametrize("n,s", [(1, "I"), (4, "IV"), (9, "IX"), (14, "XIV"), (40, "XL"),
                                 (90, "XC"), (400, "CD"), (1994, "MCMXCIV"), (3999, "MMMCMXCIX")])
def test_ida_y_vuelta(n, s):
    assert to_roman(n) == s
    assert from_roman(s) == n


def test_todo_el_rango():
    for n in range(1, 4000):
        assert from_roman(to_roman(n)) == n


@pytest.mark.parametrize("bad", [0, -1, 4000])
def test_fuera_de_rango(bad):
    with pytest.raises(ValueError):
        to_roman(bad)


@pytest.mark.parametrize("bad", ["", "IIII", "VX", "ABC", "MMMM", "IC"])
def test_romanos_invalidos(bad):
    with pytest.raises(ValueError):
        from_roman(bad)

